+++ b/source/core/utils/get-download-size.ts
@@ -0,0 +1,33 @@
+import {Buffer} from 'node:buffer';
+import {promisify} from 'node:util';
+import type {ClientRequestArgs} from 'node:http';
+import is from '@sindresorhus/is';
+import isFormData from './is-form-data.js';
+
+export default async function getDownloadSize(body: unknown, headers: ClientRequestArgs['headers']): Promise<number | undefined> {
+	if (headers && 'content-length' in headers) {
+		return Number(headers['content-length']);
+	}
+
+	if (!body) {
+		return 0;
+	}
+
+	if (is.string(body)) {
+		return Buffer.byteLength(body);
+	}
+
+	if (is.buffer(body)) {
+		return body.length;
+	}
+
+	if (body instanceof Uint8Array) {
+		return body.byteLength;
+	}
+
+	if (isFormData(body)) {
+		return promisify(body.getLength.bind(body))();
+	}
+
+	return undefined;
+}
